fn vec() -> Vec<T> {
    let mutStorage: Vec<T> = Vec { len: 0, capacity: 0, data: 0 }
}

fn push(v: Vec<T>, x: T) -> Vec<T> {
    let newLen = v.len + 1
    if newLen > v.capacity {
        let newCapacity = calculateNewCapacity(v.capacity)
        let mutNewStorage: Vec<T> = Vec { len: 0, capacity: newCapacity, data: 0 }
        for i in range(0, v.len) {
            newStorage = push(newStorage, v.data + i)
        }
        newStorage = push(newStorage, x)
        newStorage
    } else {
        let mutNewStorage: Vec<T> = v
        newStorage = push(newStorage, x)
        newStorage
    }
}

fn calculateNewCapacity(oldCapacity: Int) -> Int {
    if oldCapacity == 0 {
        return 1
    }
    return oldCapacity * 2
}

fn len(v: Vec<T>) -> Int {
    v.len
}

fn get(v: Vec<T>, i: Int) -> Option<T> {
    if i >= 0 && i < v.len {
        return Some(v.data + i)
    } else {
        return None
    }
}

fn range(a: Int, b: Int) -> Vec<Int> {
    let mutStorage: Vec<Int> = Vec { len: 0, capacity: 0, data: 0 }
    for i in range(a, b) {
        newStorage = push(newStorage, i)
    }
    newStorage
}

fn clone(x: T) -> T {
    x
}

fn str_len(s: Str) -> Int {
    let len = 0
    for i in range(0, s.len) {
        len = len + 1
    }
    len
}

fn concat(a: Str, b: Str) -> Str {
    let newLen = a.len + b.len
    let mutNewStorage: Str = Str { len: 0, data: 0 }
    for i in range(0, a.len) {
        newStorage = push(newStorage, a.data + i)
    }
    for i in range(0, b.len) {
        newStorage = push(newStorage, b.data + i)
    }
    newStorage
}

fn chars(s: Str) -> Vec<Str> {
    let mutStorage: Vec<Str> = Vec { len: 0, capacity: 0, data: 0 }
    for i in range(0, s.len) {
        let char = substr(s, i, 1)
        newStorage = push(newStorage, char)
    }
    newStorage
}

fn substr(s: Str, start: Int, end: Int) -> Str {
    let newLen = end - start
    let mutNewStorage: Str = Str { len: 0, data: 0 }
    for i in range(0, newLen) {
        newStorage = push(newStorage, s.data + start + i)
    }
    newStorage
}

fn int_to_str(n: Int) -> Str {
    let len = 0
    for i in range(0, n.len) {
        let digit = n.data + i
        if digit < 10 {
            len = len + 1
        } else {
            len = len + 2
        }
    }
    let mutNewStorage: Str = Str { len: 0, data: 0 }
    for i in range(0, n.len) {
        let digit = n.data + i
        if digit < 10 {
            newStorage = push(newStorage, 48 + digit)
        } else {
            newStorage = push(newStorage, 55 + digit)
        }
    }
    newStorage
}

fn parse_int(s: Str) -> Option<Int> {
    let isNegative = s.data == 45
    if isNegative {
        s = substr(s, 1, s.len)
    }
    let int = 0
    for i in range(0, s.len) {
        let digit = s.data + i
        if digit < 48 || digit > 57 {
            return None
        }
        int = int * 10 + (digit - 48)
    }
    if isNegative {
        return Some(-int)
    } else {
        return Some(int)
    }
}

fn to_float(n: Int) -> Float {
    n.value
}

fn trunc(x: Float) -> Int {
    if x < 0 {
        return Math.ceil(x)
    } else {
        return Math.floor(x)
    }
}

